#[test]
fn test_local_context_mut_clears_reuse_history_for_explicit_ids() {
    let env = Environment::new();
    let mut tc = TypeChecker::new(&env);
    let reused = FVarId(11);

    {
        let ctx = tc.local_context_mut();
        ctx.push_with_id(reused, Name::anon(), Expr::prop(), BinderInfo::Default);
        let popped = ctx.pop().expect("explicit FVar should be present");
        assert_eq!(popped.id, reused);
    }

    let ctx = tc.local_context_mut();
    ctx.push_with_id(reused, Name::anon(), Expr::type_(), BinderInfo::Default);
    let decl = ctx
        .get(reused)
        .expect("cache-cleared TypeChecker should allow safe explicit-id reuse");
    assert_eq!(decl.type_, Expr::type_());
}

#[test]
fn test_local_context_mut_clears_reuse_history_for_explicit_let_ids() {
    let env = Environment::new();
    let mut tc = TypeChecker::new(&env);
    let reused = FVarId(12);
    let first_value = Expr::type_();
    let second_value = Expr::prop();

    {
        let ctx = tc.local_context_mut();
        ctx.push_let_with_id(reused, Name::anon(), Expr::prop(), first_value.clone());
        let popped = ctx
            .pop()
            .expect("explicit let-bound FVar should be present");
        assert_eq!(popped.id, reused);
        assert_eq!(popped.value.as_ref(), Some(&first_value));
    }

    let ctx = tc.local_context_mut();
    ctx.push_let_with_id(reused, Name::anon(), Expr::type_(), second_value.clone());
    let decl = ctx
        .get(reused)
        .expect("cache-cleared TypeChecker should allow safe explicit let-id reuse");
    assert_eq!(decl.type_, Expr::type_());
    assert_eq!(decl.value.as_ref(), Some(&second_value));
}

#[test]
fn test_local_context_push_let_with_id_preserves_value_and_next_id() {
    let mut ctx = LocalContext::new();
    let value = Expr::type_();

    ctx.push_let_with_id(FVarId(100), Name::anon(), Expr::prop(), value.clone());

    let decl = ctx
        .get(FVarId(100))
        .expect("push_let_with_id should register the supplied FVarId");
    assert_eq!(decl.value.as_ref(), Some(&value));

    let next = ctx.push(Name::anon(), Expr::prop(), BinderInfo::Default);
    assert!(
        next.0 > 100,
        "next fresh FVarId should advance past an explicit let-binding id, got {}",
        next.0
    );
}

