#[test]
fn test_local_context_push_let_id_positive() {
    // Tests that push_let generates positive, increasing IDs
    // Mutation: += to -= would cause IDs to become negative/decreasing

    let mut ctx = LocalContext::new();

    // Push only let bindings
    let id1 = ctx.push_let(Name::anon(), Expr::prop(), Expr::prop());
    let id2 = ctx.push_let(Name::anon(), Expr::type_(), Expr::type_());
    let id3 = ctx.push_let(
        Name::anon(),
        Expr::from_kind(ExprKind::Sort(Level::succ(Level::zero()))),
        Expr::type_(),
    );

    // IDs should be reasonable (not wrapped around from underflow)
    // If -= mutation happens: 0 - 1 = u64::MAX in wrapping
    assert!(
        id1.0 < u64::MAX / 2,
        "id1 should be small, got {} (underflow?)",
        id1.0
    );
    assert!(
        id2.0 < u64::MAX / 2,
        "id2 should be small, got {} (underflow?)",
        id2.0
    );
    assert!(
        id3.0 < u64::MAX / 2,
        "id3 should be small, got {} (underflow?)",
        id3.0
    );

    // IDs should be strictly increasing
    assert!(id2.0 > id1.0, "id2 ({}) should be > id1 ({})", id2.0, id1.0);
    assert!(id3.0 > id2.0, "id3 ({}) should be > id2 ({})", id3.0, id2.0);

    // With -= mutation, after first push_let at id=0:
    // next_id becomes 0 - 1 = u64::MAX (wrapping)
    // Second push_let would get id = u64::MAX
    // So id2 would NOT be > id1
}

#[test]
fn test_local_context_lookup_scaling() {
    let _serial = crate::test_utils::serial_test_guard();
    use std::hint::black_box;
    use std::time::Instant;

    fn build_context(size: usize) -> (LocalContext, Vec<FVarId>) {
        let mut ctx = LocalContext::new();
        let mut ids = Vec::with_capacity(size);
        for _ in 0..size {
            let id = ctx.push(Name::anon(), Expr::prop(), BinderInfo::Default);
            ids.push(id);
        }
        (ctx, ids)
    }

    // Sizes selected to check scaling without long test runtime.
    let sizes = [200usize, 2000, 20000];
    let lookups = 100_000usize;
    let mut per_op_ns = Vec::with_capacity(sizes.len());

    for &size in &sizes {
        let (ctx, ids) = build_context(size);
        let start = Instant::now();
        for i in 0..lookups {
            let id = ids[i % ids.len()];
            black_box(ctx.get(id));
        }
        let elapsed = start.elapsed().as_nanos() as f64;
        per_op_ns.push(elapsed / lookups as f64);
    }

    if per_op_ns[0] > 1.0 {
        let ratio = per_op_ns[2] / per_op_ns[0];
        // For O(1) with 100x input, ratio should be ≈1. O(log n) gives ≈2.
        // Threshold 5.0 rejects O(√n) (ratio=10); see #1871.
        assert!(
            ratio < 5.0,
            "LocalContext::get scaling regression: per-op ratio {ratio:.2}x for 100x size \
             (threshold: 5x, O(√n) = 10x). sizes: {sizes:?}, per_op_ns: {per_op_ns:?}"
        );
    }
}

